routes.body:
let environment = dispatch_support::optional_string(request, "environment");
let sdk_config = dispatch_support::optional_value::<flare_im_core_sdk::client::lifecycle::SdkConfigOverlay>(request, "sdk_config")?;
session.client().init(environment, sdk_config).await?;

let conversation_id = dispatch_support::json_string(request, "conversation_id")?;
let last_seq = dispatch_support::json_u64(request, "last_seq")?;
let limit = dispatch_support::optional_i32(request, "limit").unwrap_or(50);
client.sync_messages(&conversation_id, last_seq, limit).await?;

let conversation_id = dispatch_support::json_string(request, "conversation_id")?;
let read_seq = dispatch_support::json_u64(request, "read_seq")?;
client.mark_session_read(&conversation_id, read_seq).await?;

let access_token = dispatch_support::json_string(request, "access_token")?;
let tenant_id = dispatch_support::optional_string(request, "tenant_id");
client
    .update_access_token(access_token, tenant_id.as_deref())
    .await?;

let secret = dispatch_support::optional_string(request, "secret").unwrap_or_default();
let issuer = dispatch_support::optional_string(request, "issuer").unwrap_or_default();
let user_id = dispatch_support::json_string(request, "user_id")?;
let tenant_id = dispatch_support::optional_string(request, "tenant_id");
let token = flare_im_core_sdk::client::IMClient::generate_test_token(
    &secret,
    &issuer,
    &user_id,
    tenant_id.as_deref(),
)?;

let api = session.media_api().await?;
let download_key = dispatch_support::json_string(request, "download_key")?;
let cancelled = api.cancel_user_file_download(&download_key);

let api = session.media_api().await?;
let download_key = dispatch_support::json_string(request, "download_key")?;
let display_file_name = dispatch_support::json_string(request, "display_file_name")?;
let source_path = dispatch_support::optional_string(request, "source_path");
let source_http_url = dispatch_support::optional_string_any(request, &["source_http_url", "source_url"]);
let remote_file_id = dispatch_support::optional_string(request, "remote_file_id");
let expires_in = dispatch_support::optional_i32(request, "expires_in").unwrap_or(3600);
let path = api.download_file_to_user_downloads_folder(flare_im_core_sdk::application::UserFileDownloadRequest {
    download_key,
    display_file_name,
    source_path,
    source_http_url,
    remote_file_id,
    expires_in,
    on_progress: None,
}).await?;
